def build_response(status, data=None):
    if data is None:
        data = {}
    return {"status": status, "ok": status < 400, "data": data}

print(build_response(404))

def validate_user(payload, strict=False):
    errors = []
    if "@" not in payload.get("email", ""):
        errors.append("invalid email")
    age = payload.get("age")
    if not isinstance(age, int) or age < 13:
        errors.append("invalid age")
    if strict and "name" not in payload:
        errors.append("missing name")
    return errors

print(validate_user({"email": "neo@grid.io", "age": 9}))
